    \label{fig:rel_fluc}
\end{figure}

\section{IPR of Scrooge states}
\label{sm:scrooge_magic}

Here we derive Eq.~\eqref{eq:scrooge_ipr_main} of the main text, which gives expressions for the IPR averaged over Scrooge states, first in the regime of fixed nonzero $\beta$ in the thermodynamic limit and then for fixed $N$ as $\beta \to 0$. We consider integer $\alpha$ in this section.

\subsection{Scrooge IPR for $N \to \infty$ and fixed $\beta$}

For every Haar random state $\ket{\phi}$, we approximate the Scrooge-random state as~\cite{mok2026universalityscrooge,mcginley2025scrooge}
\begin{equation}
    \ket{\psi} = \sqrt{D \sigma} \ket{\phi}.
\end{equation}
The $k$th moment of this ensemble is
\begin{equation}
    \tilde{\rho}_\text{Scr.}^{(k)}(\sigma) = \Eset{\phi \sim \text{Haar}(D)} \parens{\ket{\psi}\bra{\psi}}^{\otimes k} = (D \sigma)^{\otimes k} \rho_{\text{Haar}}^{(k)}.
\end{equation}
Comparing to the $k$th moment of the actual Scrooge ensemble, this has an additive error $\bigO{k \norm{\sigma}_2}$ and relative error $\bigO{4^k k \norm{\sigma}_2}$. Indeed, even though $\ket{\psi}$ is, strictly speaking, unnormalized (except in the Haar limit $\sigma \to I/D$), its norm is close to unity,
\begin{equation}
    \E_\psi \sparens{\braket{\psi|\psi}^k} = 1 + \bigO{k^2 \norm{\sigma}_2^2},
\end{equation}
up to a purity correction which is expected to be exponentially small in system size in a typical quantum many-body state~\cite{mok2026universalityscrooge}. Assuming the quenched average is close to the analytically calculated annealed average~\cite{sierant2026theorymagicphasetransitions}, we approximate
\begin{align} \label{eq:self_avg}
 \Eset{\psi \sim \text{Scr.}(\sigma)} (\widetilde M_\alpha(\ket \psi)) \approx \frac{1}{1-\alpha}\log_2\left(\frac{\mathbb E_\psi(\ipr_\alpha)-1}{D-1}\right).
\end{align}
Let $H = \sum_{Q \neq I} a_Q Q$. Using the approximate Scrooge ensemble,
\begin{equation}
    \Eset{\psi \sim \text{Scr.}(\sigma)}\ipr_\alpha(\psi) \approx \sum_{\pi \in S_{2\alpha}} \sum_{P} \Tr((P \sigma)^{\otimes 2\alpha} \hat{\pi}).
\label{eq:scrooge_magic_approx}
\end{equation}
Let us define $t_m(P) = \Tr[(P \sigma)^m]$ and write
\begin{equation}
    \sigma = \frac{1}{D} \sum_P r_P P,
\end{equation}
with $t_1(P) \equiv r_P$. The following inequalities will be useful:
\begin{equation}
    |t_m(P)| \leq \Tr |P \sigma|^m = \Tr(\sigma^m).
\end{equation}
For any $m \geq 2$,
\begin{equation}
    \sum_P |t_1(P)|^m = \sum_P |{r_P}|^m \leq \parens{\sum_P {r_P}^2}^{m/2} = \parens{D \Tr(\sigma^2)}^{m/2}.
\end{equation}
Finally, we note that for generic high-temperature Gibbs states, 
\begin{equation}
    \Tr(\sigma^m) = D^{1-m} \exp\parens{\bigO{N\beta^2}}.
\end{equation}
Now, let us evaluate Eq.~\eqref{eq:scrooge_magic_approx} for $\alpha = 2$. We can write
\begin{equation}
    \Eset{\psi \sim \text{Scr.}(\sigma)}\ipr_2(\psi) \approx \sum_P ({t_1}^4 + 3 {t_2}^2) + R,
\end{equation}

\subsubsection{Bounding $|R|$ for $\alpha = 2$} 

\noindent The remainder term $R$ is bounded by
\begin{equation}
    |R| \leq C \sum_{P} \parens{ |t_2 {t_1}^2| + |t_3 t_1| + |t_4|},
\end{equation}
for some constant $C$ (which comes from the combinatorial factor). Noting that $PQP = f_{PQ} Q$ where $f_{PQ} \in \{\pm 1\}$ is the sign factor,
\begin{equation}
\begin{aligned}
    t_2 &= \Tr(P \sigma P \sigma) \\&= \frac{1}{D^2} \sum_{Q,Q'} \Tr(P Q P Q') r_Q r_{Q'} \\
    &= \frac{1}{D} \sum_{Q} f_{PQ} {r_Q}^2,
\end{aligned}
\end{equation}
and thus
\begin{equation}
    \sum_P t_2(P)^2 = \frac{1}{D^2} \sum_{P,Q,Q^\prime} f_{PQ} f_{PQ^\prime} {r_Q}^2 {r_{Q^\prime}}^2 = \sum_P {t_1}^4 = \sum_P {r_P}^4,
\end{equation}
using the orthogonality relation $\sum_P f_{PQ} f_{PQ^\prime} = D^2 \delta_{QQ^\prime}$ ($f_{PQ}$ is the character of $\mathcal{P}_N$, from which orthogonality holds). This implies that
\begin{equation}
    \Eset{\psi \sim \text{Scr.}(\sigma)}\ipr_2(\psi) \approx 4\sum_P {r_P}^4 + R.
\end{equation}
The first term is four times the IPR of $\sigma$. To bound the remainder term, we use the aforementioned inequalities to get
\begin{equation}
    |R| = \bigO{ D \Tr^2(\sigma^2) + D^{3/2} \Tr(\sigma^3) \Tr^{1/2}(\sigma^2) + D^2 \Tr(\sigma^4)  }.
\end{equation}
Now, substituting the generalized purities of $\sigma$ at high temperature, we get
\begin{equation}
    |R| = \bigO{\frac{1}{D} \exp(\bigO{N \beta^2})}.
\end{equation}
This means that for a sufficiently high constant temperature, $|R|$ is exponentially small in $N$, and we establish
\begin{equation}
    \Eset{\psi \sim \text{Scr.}(\sigma)}\ipr_2(\psi) \approx 4\sum_P {r_P}^4 + \bigO{e^{-cN}} = 4 \ipr_2(\sigma) + \bigO{e^{-cN}}.
\end{equation}
For constant temperature, we expect $\ipr_\alpha(\sigma_\beta)$ to be exponentially large in $N$, so the $-1$ term in the numerator of Eq.~\eqref{eq:self_avg} is negligible, like $|R|$ in the thermodynamic limit. Taking the logarithm, this implies that to leading order in $N$,
\begin{equation}
    M_2 \approx \fsre_2 \approx N - \log_2 (\ipr_2(\sigma_\beta)).
\end{equation}
Using a cluster expansion, we obtain the extensive behavior of the logarithm of the IPR (and subsequently volume-law corrections to the SRE and fSRE),
\begin{equation}
    \ln(\ipr_2(\sigma_\beta)) = {\beta^4 \sum_{Q \neq I} a_Q^4 + \bigO{N\beta^5}},
\end{equation}
so we obtain
\begin{equation} \label{eq:m2_app}
    M_2 \approx \fsre_2 \approx N (1 - c_2\beta^4  + \bigO{\beta^5}),~c_2 = \frac{\sum a_Q^4}{N\ln 2}.
\end{equation}

\subsubsection{Bounding $|R|$ for $\alpha > 2$}

We want to generalize the bounding of the remainder term $R$ from the approximate Scrooge average for arbitrary integer $\alpha > 2$. The approximate Scrooge average involves summing over all permutations $\pi \in S_{2\alpha}$
\begin{align}
\Eset{\psi \sim \text{Scr.}(\sigma)}\ipr_\alpha(\psi) \approx \sum_{\pi \in S_{2\alpha}} \sum_P \text{Tr}((P\sigma)^{\otimes 2\alpha} \hat{\pi}).
\end{align}
Any permutation $\pi \in S_{2\alpha}$ can be decomposed into disjoint cycles. Let the cycle type be characterized by a tuple $\vec{k} = (k_1, k_2, \dots, k_{2\alpha})$, where $k_j$ is the number of cycles of length $j$. The power inside the traces multiplied by the power outside must sum to $2\alpha$, the total length of all cycles. This imposes the strict constraint
\begin{align}
\sum_{j=1}^{2\alpha} j \cdot k_j = 2\alpha.
\end{align}
For a given permutation of cycle type $\vec{k}$, the trace evaluates to
\begin{align}
\text{Tr}((P\sigma)^{\otimes 2\alpha} \hat{\pi}) = \prod_{j=1}^{2\alpha} [t_j(P)]^{k_j},
\end{align}
where $t_j(P) = \text{Tr}((P\sigma)^j)$ and $t_1(P) \equiv r_P \equiv c_P$. Therefore, the total sum is grouped by cycle structures, weighted by a combinatorial factor $C(\vec{k})$ (the number of permutations of that cycle type, which depends \textit{only} on $\alpha$, not $N$)
