\section{Channel reduction and support}
\label{app:channel-reduction}

Matrix logarithms in the main algorithm must be evaluated on fixed faithful
output spaces, whereas the unreduced protocol maps may contain null
directions.  This appendix removes those directions by exact support
compression, proves that the compressed maps remain CPTP, and verifies that
the compact DM CV block representation preserves the objective.  Set
\begin{equation}
  \begin{aligned}
    Q&\coloneqq \operatorname{supp}(\cG_0(\mathbbm1_{\mathcal H})),\\
    R&\coloneqq \operatorname{supp}(\Phi_0(\cG_0(\mathbbm1_{\mathcal H})))
  \end{aligned}
  \label{eq:channel-support-projectors}
\end{equation}
as orthogonal projections on $\mathcal K_0$, with $\cG_0$ and $\Phi_0$ the uncompressed maps. Let
$\mathcal K_G\coloneqq \operatorname{ran}Q$ and
$\mathcal K_Z\coloneqq \operatorname{ran}R$, and let
$V_Q:\mathcal K_G\hookrightarrow\mathcal K_0$ and
$V_R:\mathcal K_Z\hookrightarrow\mathcal K_0$ be the canonical isometric
inclusions.  Thus
$V_Q^\dagger V_Q=\mathbbm1_{\mathcal K_G}$,
$V_QV_Q^\dagger=Q$,
$V_R^\dagger V_R=\mathbbm1_{\mathcal K_Z}$, and
$V_RV_R^\dagger=R$.  Define
\begin{align}
  \cG:\mathcal B(\mathcal H)&\longrightarrow\mathcal B(\mathcal K_G),
  &\cG(X)&\coloneqq V_Q^\dagger\cG_0(X)V_Q,
  \label{eq:compressed-preprocessing-map}\\
  \Phi:\mathcal B(\mathcal K_G)&\longrightarrow\mathcal B(\mathcal K_Z),
  &\Phi(Y)&\coloneqq V_R^\dagger
    \Phi_0(V_QYV_Q^\dagger)V_R,
  \label{eq:compressed-pinching-map}
\end{align}
Then, the combined map is given by 
\begin{equation}
  \cZ\coloneqq \Phi\circ\cG:
    \mathcal B(\mathcal H)\longrightarrow\mathcal B(\mathcal K_Z).
  \label{eq:compressed-composed-map}
\end{equation}
For $X\succeq0$,
\begin{equation}
  0\preceq\cG_0(X)
  \preceq\norm{X}_{\mathrm{op}}\cG_0(\mathbbm1_{\mathcal H}).
  \label{eq:preprocessing-support-domination}
\end{equation}
Hence every positive output of $\cG_0$ is supported on $Q$.  Decomposing a
general operator into a linear combination of positive operators gives the
same support statement for the complete range.  Compression by $V_Q$ loses
neither trace nor nonzero spectrum and preserves complete positivity, so
$\cG$ is CPTP.  By definition of $Q$,
$\cG(\mathbbm1_{\mathcal H})\succ0$ on $\mathcal K_G$.

On $\mathcal K_G$ there are constants $0<c\le C<\infty$ such that
\begin{equation}
  cV_QV_Q^\dagger
  \preceq\cG_0(\mathbbm1_{\mathcal H})
  \preceq CV_QV_Q^\dagger.
  \label{eq:preprocessing-support-equivalence}
\end{equation}
Applying the positive map $\Phi_0$ shows that
\begin{equation}
  \operatorname{supp}(\Phi_0(V_QV_Q^\dagger))=R.
  \label{eq:pinching-output-support}
\end{equation}
Every output of $Y\mapsto\Phi_0(V_QYV_Q^\dagger)$ is consequently supported
on $R$.  The second compression again preserves trace and complete
positivity; hence $\Phi$ and $\cZ$ are CPTP and
$\Phi(\mathbbm1_{\mathcal K_G})\succ0$ on $\mathcal K_Z$ and
$\cZ(\mathbbm1_{\mathcal H})\succ0$ on $\mathcal K_Z$.  In particular, if
$\rho\succeq b\mathbbm1_{\mathcal H}$ for $b>0$, then
\begin{equation}
  \begin{aligned}
    \cG(\rho)&\succeq b\cG(\mathbbm1_{\mathcal H})\succ0,\\
    \cZ(\rho)&\succeq b\cZ(\mathbbm1_{\mathcal H})\succ0.
  \end{aligned}
  \label{eq:faithful-channel-outputs}
\end{equation}
Thus all output logarithms at positive iterates are taken on fixed exact
supports.

For the normalized DM CV construction, specialize
$\mathcal H=\mathcal H_A\otimes\mathcal H_B$ and let
$\{E_a\in\mathcal B(\mathcal H_B):a\in\mathsf A\}$ be a POVM, so
$E_a\succeq0$ and $\sum_aE_a=\mathbbm1_{\mathcal H_B}$.  With key register
space $\mathcal H_Z\coloneqq \mathbb C^{|\mathsf A|}$ and basis
$\{\ket a:a\in\mathsf A\}$, set $\mathcal K_0\coloneqq \mathcal H_A\otimes\mathcal H_B\otimes\mathcal H_Z,$
\begin{equation}
  \begin{aligned}
    &V:\mathcal H\longrightarrow\mathcal K_0,
    &V\coloneqq \sum_{a\in\mathsf A}
       \mathbbm1_{\mathcal H_A}\otimes\sqrt{E_a}\otimes\ket a
  \end{aligned}
  \label{eq:appendix-dmcv-naimark-data}
\end{equation}
with projectors $P_a\coloneqq \mathbbm1_{\mathcal H_A\otimes\mathcal H_B} \otimes\ket a\!\bra a$. Then the preprocessing map can be written as $\cG_0(X)\coloneqq VXV^\dagger$, where $V^\dagger V=\sum_a\mathbbm1_{\mathcal H_A}\otimes E_a
=\mathbbm1_{\mathcal H}$.  For
$\mathcal K_a\coloneqq \operatorname{ran}(P_aV)\subseteq\mathcal K_0$, let
$V_a:\mathcal K_a\hookrightarrow\mathcal K_0$ be the inclusion and define
\begin{equation}
  \begin{aligned}
    A_a&\coloneqq V_a^\dagger P_aV:\mathcal H\longrightarrow\mathcal K_a,\\
    \mathcal K_Z&\coloneqq \bigoplus_{a\in\mathsf A}\mathcal K_a.
  \end{aligned}
  \label{eq:appendix-dmcv-block-spaces}
\end{equation}
Since $V_aV_a^\dagger$ projects onto $\operatorname{ran}(P_aV)$,
\begin{equation}
  A_a^\dagger A_a
  =V^\dagger P_aV_aV_a^\dagger P_aV
  =V^\dagger P_aV.
  \label{eq:dmcv-block-completeness-step}
\end{equation}
Summing over $a$ gives
$\sum_aA_a^\dagger A_a=\mathbbm1_{\mathcal H}$, so the compact block map
\begin{equation}
  \cZ:\mathcal B(\mathcal H)\longrightarrow\mathcal B(\mathcal K_Z),
  \qquad
  \cZ(X)\coloneqq \bigoplus_{a\in\mathsf A}A_aXA_a^\dagger,
  \label{eq:appendix-dmcv-compact-channel}
\end{equation}
is CPTP.  Each $A_a$ is onto its declared range, and $\cZ(\rho)$ has the same
nonzero block spectra as $\Phi_0(V\rho V^\dagger)$.  Since $V$ is an
isometry, $S(V\rho V^\dagger)=S(\rho)$, and hence the normalized DM CV
objective is $F(\rho)=S(\cZ(\rho))-S(\rho)$.

\section{Relative entropy identities}
\label{app:relative-entropy-identities}

The convergence analysis repeatedly needs exact entropy decompositions that
remain valid for boundary states.  This appendix establishes the pinching,
channel Bregman, affine projection, and moving reference identities used to
turn individual Gibbs steps into telescoping estimates.

\subsection{Pinching entropy and Pythagorean identities}
\label{app:pinching-identities}

\begin{lem}[Pinching entropy and Pythagorean identities]
  \label{lem:pinching-identities}
  Let $\cH$ be a finite-dimensional Hilbert space and let
  $\{\widehat P_b:b\in\mathsf B\}\subset\mathcal B(\mathcal H)$ be a finite
  family of mutually orthogonal projections summing to
  $\mathbbm1_{\mathcal H}$.  Define the pinching
  $\Phi:\mathcal B(\mathcal H)\to\mathcal B(\mathcal H)$ by
  $\Phi(X)\coloneqq \sum_{b\in\mathsf B} P_b X P_b$.  For every
  $X\in\mathcal B(\mathcal H)$ with $X\succeq0$,
  \begin{equation}
    D(X\Vert\Phi(X))=S(\Phi(X))-S(X),
    \label{eq:boundary-pinching-entropy}
  \end{equation}
  including when $X$ is singular.  If $\tau$ and $\sigma$ are density
  operators on $\mathcal H$ and $\sigma\succ0$, then
  \begin{equation}
    D(\tau\Vert\Phi(\sigma))
    =D(\tau\Vert\Phi(\tau))
     +D(\Phi(\tau)\Vert\Phi(\sigma)).
    \label{eq:pinching-pythagorean-appendix}
  \end{equation}
\end{lem}

\begin{proof}
Let $s$ be the number of nonzero pinching blocks.  The pinching inequality
