\appendix
\section{Proof of Theorem~\ref{Theorem:lower bound of samples}}
\label{appendix:state-to-query}
Let $\rho_+$ and $\rho_-$ be the qubit states to be discriminated, defined by
\begin{equation}
	\rho_+:=
	\begin{pmatrix}
		\frac{1}{2}+\delta & 0 \\
		0 & \frac{1}{2}-\delta
	\end{pmatrix},
	\quad \rho_-:=
	\begin{pmatrix}
		\frac{1}{2}-\delta & 0 \\
		0 & \frac{1}{2}+\delta
	\end{pmatrix}.
	\label{equation:discriminated quantum state}
\end{equation}
Here, $\delta\in(0,1/4)$.
We evaluate the sample complexity required to distinguish them.

\begin{Lem}
	\label{Lemma:lower bound of sample to discriminate the states}
	Suppose we are promised that a quantum state $\rho$ is either $\rho_+$ or $\rho_-$.
	To correctly determine whether $\rho$ is $\rho_+$ or $\rho_-$ with success probability at least $2/3$,
	\begin{equation}
		\bigOmega{\frac{1}{\delta^2}}
	\end{equation}
	copies of $\rho$ are required.
\end{Lem}

\begin{proof}
	The optimal strategy for maximizing the success probability of identifying $\rho$ is the Helstrom measurement \cite{Helstrom1969, Holevo1973}.
	If we are allowed to use $n_{\mathrm{disc}}$ copies of $\rho$, the success probability $p_{\mathrm{success}}$ satisfies
	\begin{equation}
		p_{\mathrm{success}} \le \frac{1}{2} +\frac{1}{4} \left\| \rho_+^{\otimes n_{\mathrm{disc}}} -\rho_-^{\otimes n_{\mathrm{disc}}} \right\|_1.
	\end{equation}
	Since $\rho_+$ and $\rho_-$ commute, their trace distance is the same as the classical total variation distance up to the conventional factor of two:
	\begin{equation}
		\left\| \rho_+^{\otimes n_{\mathrm{disc}}} -\rho_-^{\otimes n_{\mathrm{disc}}} \right\|_1 = 2d_{\mathrm{TV}} \left( p_+^{\otimes n_{\mathrm{disc}}}, p_-^{\otimes n_{\mathrm{disc}}} \right),
	\end{equation}
	where
	\begin{equation}
		p_+=\left(\frac{1}{2}+\delta,\frac{1}{2}-\delta\right), \qquad p_-=\left(\frac{1}{2}-\delta,\frac{1}{2}+\delta\right).
	\end{equation}
	Using Pinsker's inequality \cite{Brillinger1964},
	\begin{align}
		d_{\mathrm{TV}} \left( p_+^{\otimes n_{\mathrm{disc}}}, p_-^{\otimes n_{\mathrm{disc}}} \right) &\le \sqrt{ \frac{1}{2} D_{\mathrm{KL}} \left( p_+^{\otimes n_{\mathrm{disc}}} \middle\| p_-^{\otimes n_{\mathrm{disc}}} \right) } \nonumber\\
		&= \sqrt{ \frac{n_{\mathrm{disc}}}{2} D_{\mathrm{KL}}(p_+\|p_-) } \nonumber\\
		&= \sqrt{ \frac{n_{\mathrm{disc}}}{2} \,2\delta \log\frac{1+2\delta}{1-2\delta} } \nonumber\\
		&\le \sqrt{ \frac{n_{\mathrm{disc}}}{2} \,2\delta\cdot6\delta } \nonumber\\
		&= \sqrt{6n_{\mathrm{disc}}\delta^2}.
	\end{align}
	Here, we used
	\begin{align}
		\log(1+2\delta)&\le2\delta, \\
		-\log(1-2\delta)&\le4\delta \qquad \left(\delta\in(0,1/4)\right).
	\end{align}
	To achieve success probability at least $2/3$, we require
	\begin{equation}
		\frac{1}{3} \le d_{\mathrm{TV}} \left( p_+^{\otimes n_{\mathrm{disc}}}, p_-^{\otimes n_{\mathrm{disc}}} \right) \le \sqrt{6n_{\mathrm{disc}}\delta^2}.
	\end{equation}
	Therefore,
	\begin{equation}
		n_{\mathrm{disc}} = \bigOmega{\frac{1}{\delta^2}}.
	\end{equation}
\end{proof}

Next, we show how quantum channels that simulate a block-encoding unitary channel can be used to distinguish $\rho_+$ and $\rho_-$ with sufficient probability.
We note that an $(\alpha,a,0)$-block encoding of $\rho_\pm$ can also be viewed as an $(\alpha,a+1,0)$-block encoding of the scalar $1/2\pm\delta$.
Our strategy is to distinguish the singular values using a polynomial approximation to a superposition of sign functions, namely
\begin{equation}
	U_{\rho_\pm} =
	\begin{pmatrix}
		\frac{\frac{1}{2}\pm\delta}{\alpha} & \ast \\
		\ast & \ast
	\end{pmatrix}
	\quad \xrightarrow{\mathrm{QSVT}} \quad
	\begin{pmatrix}
		f\left(\frac{\frac{1}{2}\pm\delta}{\alpha}\right) & \ast \\
		\ast & \ast
	\end{pmatrix}.
\end{equation}
Here, $f$ is the function defined in \eqref{equation:g}.
We use the following polynomial approximation to the sign function.

\begin{Lem}[\cite{Gilyen2019}, Lemma 25]
	For all $\gamma>0$ and $\varepsilon'\in(0,1/2)$, there exists an efficiently computable odd polynomial $P\in\mathbb{R}[x]$ of degree
	\begin{equation}
		\deg P = \bigO{\frac{\log(1/\varepsilon')}{\gamma}}
	\end{equation}
	such that
	\begin{align}
		\|P\|_{\infty,[-2,2]}&\le1, \\
		\|P-\operatorname{sign}\|_{ \infty,\, [-2,2]\setminus(-\gamma/2,\gamma/2) } &\le\varepsilon'.
	\end{align}
	\label{Lemma:approximate sign function}
\end{Lem}

We use the convention
\begin{equation}
	\operatorname{sign}(x):=
	\begin{cases}
		1, & x>0,\\
		0, & x=0,\\
		-1, & x<0.
	\end{cases}
\end{equation}
Define
\begin{equation}
	f(x):= \frac{1}{4} \left( \operatorname{sign}\left(x+\frac{1}{2\alpha}\right) - \operatorname{sign}\left(x-\frac{1}{2\alpha}\right) \right),
	\label{equation:g}
\end{equation}
and let
\begin{equation}
	\widetilde{f}(x):= \frac{1}{4} \left( P\left(x+\frac{1}{2\alpha}\right) - P\left(x-\frac{1}{2\alpha}\right) \right),
\end{equation}
where we set $\gamma=\delta/\alpha$ in Lemma~\ref{Lemma:approximate sign function}.

\begin{Lem}
	Let
	\begin{equation}
		D_{\delta,\alpha} := [-1,1] \setminus \left( \left[-\frac{1+\delta}{2\alpha},-\frac{1-\delta}{2\alpha}\right] \cup \left[\frac{1-\delta}{2\alpha},\frac{1+\delta}{2\alpha}\right] \right).
	\end{equation}
	Then $\widetilde{f}$ satisfies the following properties:
	\begin{itemize}
		\item $\|\widetilde{f}\|_{\infty,[-1,1]}\le\frac{1}{2}$.\
        \item $\|\widetilde{f}-f\|_{\infty,D_{\delta,\alpha}}\le\frac{\varepsilon'}{2}$.
		\item $\widetilde{f}$ is an even polynomial and
		\begin{equation}
			\deg\widetilde{f} \le \deg P = \bigO{ \frac{\alpha}{\delta} \log\left(\frac{1}{\varepsilon'}\right) }.
		\end{equation}
	\end{itemize}
	\label{Lemma:approximate g}
\end{Lem}

\begin{proof}
	\begin{itemize}
		\item We have
		\begin{align}
			\|\widetilde{f}\|_{\infty,[-1,1]} &= \frac{1}{4} \left\| P\left(x+\frac{1}{2\alpha}\right) - P\left(x-\frac{1}{2\alpha}\right) \right\|_{\infty,[-1,1]} \nonumber\\
			&\le \frac{1}{4} \left( \|P\|_{\infty,[-1+1/(2\alpha),\,1+1/(2\alpha)]} + \|P\|_{\infty,[-1-1/(2\alpha),\,1-1/(2\alpha)]} \right) \nonumber\\
			&\le\frac{1}{2}.
		\end{align}

		\item Define
		\begin{equation}
			\Delta_\pm(x) := P\left(x\pm\frac{1}{2\alpha}\right) - \operatorname{sign}\left(x\pm\frac{1}{2\alpha}\right).
		\end{equation}
		Then
		\begin{align}
			\|\widetilde{f}-f\|_{\infty,D_{\delta,\alpha}} &= \frac{1}{4} \|\Delta_+-\Delta_-\|_{\infty,D_{\delta,\alpha}} \nonumber\\
			&\le \frac{1}{4} \left( \|\Delta_+\|_{\infty,D_{\delta,\alpha}} + \|\Delta_-\|_{\infty,D_{\delta,\alpha}} \right) \nonumber\\
			&\le\frac{\varepsilon'}{2}.
		\end{align}

		\item Since $P$ is odd,
		\begin{align}
			\widetilde{f}(-x) &= \frac{1}{4} \left( P\left(-x+\frac{1}{2\alpha}\right) - P\left(-x-\frac{1}{2\alpha}\right) \right) \nonumber\\
			&= \frac{1}{4} \left( -P\left(x-\frac{1}{2\alpha}\right) + P\left(x+\frac{1}{2\alpha}\right) \right) \nonumber\\
			&= \widetilde{f}(x).
		\end{align}
		Thus, $\widetilde{f}$ is even.
		Since shifts and linear combinations do not increase the degree,
		\begin{equation}
			\deg\widetilde{f} \le \deg P = \bigO{ \frac{\alpha}{\delta} \log\left(\frac{1}{\varepsilon'}\right) }.
		\end{equation}
	\end{itemize}
\end{proof}

\begin{Lem}[\cite{Gilyen2019}, Theorem 26]
Let $U_\rho$ be an $(\alpha,a+1,0)$-block encoding of a scalar
$\rho_{11}\in[0,1]$, and let $\mathcal{U}_\rho$ and
$\mathcal{U}_\rho^\dagger$ be the unitary channels induced by
$U_\rho$ and $U_\rho^\dagger$, respectively.
Assume that $\alpha=\Theta(1)$.
Then the unitary channel induced by a $(1,a+2,0)$-block-encoding
unitary of $\widetilde{f}(\rho_{11}/\alpha)$ can be implemented using
\begin{equation}
    l=\bigO{\frac{1}{\delta}
    \log\left(\frac{1}{\varepsilon'}\right)}
\end{equation}
queries in total to $\mathcal{U}_\rho$ and
$\mathcal{U}_\rho^\dagger$, together with known phase gates and
controlled reflections about $\ket{0}^{\otimes(a+1)}$.
	\label{lemma:QSVT}
\end{Lem}

\begin{proof}
	Let
	\begin{equation}
		\Pi := \ket{0}\!\bra{0}^{\otimes(a+1)}.
	\end{equation}
	Then
	\begin{equation}
		\frac{\rho_{11}}{\alpha} \ket{0}\!\bra{0}^{\otimes(a+1)} = \Pi U_\rho\Pi.
	\end{equation}
	By Corollary 18 of \cite{Gilyen2019} and Lemma~\ref{Lemma:approximate g}, there exists a real vector
	\begin{equation}
		\Phi = (\phi_1,\phi_2,\ldots,\phi_l) \in \mathbb{R}^l
	\end{equation}
	such that
	\begin{align}
		\widetilde{f}(\Pi U_\rho\Pi) &= (\bra{+}\otimes\Pi) \left( \ket{0}\!\bra{0}\otimes U_\Phi + \ket{1}\!\bra{1}\otimes U_{-\Phi} \right) (\ket{+}\otimes\Pi), \\
		U_\Phi &:= \prod_{j=1}^{l/2} \left( e^{i\phi_{2j-1}(2\Pi-I)} U_\rho^\dagger e^{i\phi_{2j}(2\Pi-I)} U_\rho \right).
		\label{equation:QSVT circuit}
	\end{align}
	Therefore,
	\begin{equation}
		(H\otimes I) \left( \ket{0}\!\bra{0}\otimes U_\Phi + \ket{1}\!\bra{1}\otimes U_{-\Phi} \right) (H\otimes I)
	\end{equation}
	is a block encoding of $\widetilde{f}(\rho_{11}/\alpha)$.
	The unknown unitaries $U_\rho$ and $U_\rho^\dagger$ are applied unconditionally in the same order and the same number of times in the two branches of the multiplexed unitary; only the known phase gates $e^{\pm i\phi_k(2\Pi-I)}$ are coherently controlled by the branch qubit. Hence, the construction does not require controlled access to either $U_\rho$ or $U_\rho^\dagger$. Consequently, the unitary channel induced by the above block-encoding unitary can be implemented using $l$ queries in total to $\mathcal{U}_\rho$ and $\mathcal{U}_\rho^\dagger$.
\end{proof}

\begin{Lem}[\cite{gilyén2022}, Corollary 12]
	For every block encoding $\widetilde{U}\in\mathbb{C}^{d\times d}$ of $\widetilde{A}\in\mathbb{C}^{\widetilde{n}\times n}$ with $d\ge4(\widetilde{n}+n)$, and for every $A\in\mathbb{C}^{\widetilde{n}\times n}$ satisfying
	\begin{equation}
		\|A-\widetilde{A}\|_\infty + \left\| \frac{A+\widetilde{A}}{2} \right\|_\infty^2 \le1,
	\end{equation}
	there exists a block encoding $U\in\mathbb{C}^{d\times d}$ of $A$ satisfying
	\begin{equation}
		\|U-\widetilde{U}\|_\infty \le \sqrt{ \frac{2}{ 1- \left\| \frac{A+\widetilde{A}}{2} \right\|_\infty^2 } } \, \|A-\widetilde{A}\|_\infty.
	\end{equation}
	\label{lemma:robustness of block-encoding}
\end{Lem}

Lemma~\ref{lemma:robustness of block-encoding} bounds the operator-norm distance between suitable block encodings in terms of the distance between the encoded matrices.
Choose $\varepsilon'=0.01$.
On the domain $D_{\delta,\alpha}$, the intended estimate is
\begin{align}
	\|f-\widetilde{f}\|_{\infty,D_{\delta,\alpha}} + \left\| \frac{f+\widetilde{f}}{2} \right\|_{\infty,D_{\delta,\alpha}}^2 &\le 2\varepsilon' + \frac{1}{4}(1+\varepsilon')^2 \\
	&<1.
	\label{equation:robustness-condition-application}
\end{align}
Thus, the condition of Lemma \ref{lemma:robustness of block-encoding} is satisfied. Therefore, there exists a block encoding $U_f$ of $f$ such that
\begin{align}
	\|U_f-U_{\widetilde{f}}\|_\infty &\le \frac{\varepsilon'}{2}\sqrt{\frac{2}{1- \frac{1}{4}}} \\
    &=\sqrt{\frac{2}{3}}\varepsilon'\\
	&< \frac{1}{120}.
\end{align}
Consequently, using the relationship between the diamond norm and the operator norm \cite{Kitaev1997}, we obtain
\begin{equation}
	\|\mathcal{U}_f-\mathcal{U}_{\widetilde{f}}\|_\diamond \le 2\|U_f-U_{\widetilde{f}}\|_\infty < \frac{1}{60}.
\end{equation}
If the approximate channels $\mathcal{E}_\rho$ and $\mathcal{E}_\rho^\dagger$ are used $l$ times in total, a hybrid argument gives
\begin{equation}
	\|\mathcal{E}_{\widetilde{f}}-\mathcal{U}_{\widetilde{f}}\|_\diamond \le l\varepsilon.
\end{equation}
Overall,
\begin{equation}
	\|\mathcal{E}_{\widetilde{f}}-\mathcal{U}_f\|_\diamond \le l\varepsilon + \frac{1}{60}=:\tau.
\end{equation}

Now, let us focus on the discrimination task using the above QSVT construction.

\begin{Lem}
	Suppose that $\rho$ is promised to be either $\rho_+$ or $\rho_-$ in \eqref{equation:discriminated quantum state}, and that we are given channels $\mathcal{E}_\rho$ and $\mathcal{E}_\rho^\dagger$ that approximate $\mathcal{U}_\rho$ and $\mathcal{U}_\rho^\dagger$ to diamond-norm precision $\varepsilon$.
	Choose the parameter $\delta$ defining $\rho_+$ and $\rho_-$ so that $\delta=\Theta(\varepsilon)$.
	Then there exists an algorithm that identifies whether the given channels correspond to $\rho_+$ or $\rho_-$ with constant success probability, using
	\begin{equation}
		\bigO{\frac{1}{\varepsilon}}
	\end{equation}
	queries to $\mathcal{E}_\rho$ and $\mathcal{E}_\rho^\dagger$.
	\label{lemma:discriminate with queries}
\end{Lem}

\begin{proof}
	Suppose that we have access to $\mathcal{E}_\rho$ and $\mathcal{E}_\rho^\dagger$.
	Using the QSVT circuit from Lemma~\ref{lemma:QSVT}, we obtain the channel $\mathcal{E}_{\widetilde{f}}$.
	The two channels $\mathcal{E}_\rho$ and $\mathcal{E}_\rho^\dagger$ are used the same number of times.
	We apply $\mathcal{E}_{\widetilde{f}}$ to $\ket{0}\!\bra{0}^{\otimes(a+2)}$ and measure the projector
	\begin{equation}
		\Pi = \ket{0}\!\bra{0}^{\otimes(a+2)}.
	\end{equation}
	For every state $\sigma$,
	\begin{equation}
		\left| \Tr\left[ \Pi\mathcal{E}_{\widetilde{f}}(\sigma) \right] - \Tr\left[ \Pi\mathcal{U}_f(\sigma) \right] \right| \le \|\mathcal{E}_{\widetilde{f}}-\mathcal{U}_f\|_\diamond \le l\varepsilon+\frac{1}{60}.
	\end{equation}

    If $\rho=\rho_+$, then
    \begin{equation}
        f\left(\frac{1/2+\delta}{\alpha}\right)=0.
    \end{equation}
    Choose $\delta=C\varepsilon$, where $C>0$ is a sufficiently large constant such that $l\varepsilon\le 1/120$.
    Such a constant exists because $\alpha=\Theta(1)$ and $\varepsilon'=0.01$ is fixed.
    Therefore, in each repetition,
    \begin{equation}
        p_+:=\Pr[\widehat{\Pi}]\le\tau\le\frac{1}{40}.
    \end{equation}

	On the other hand, if $\rho=\rho_-$, then
    \begin{equation}
        f\left(\frac{1/2-\delta}{\alpha}\right)=\frac{1}{2}.
    \end{equation}
    Since the corresponding ideal postselection probability is $1/4$,
    \begin{equation}
        p_-:=\Pr[\widehat{\Pi}]\ge\frac{1}{4}-\tau\ge\frac{9}{40}.
    \end{equation}
    Repeat the above procedure independently five times.
    Output $\rho_-$ if the outcome associated with $\widehat{\Pi}$ occurs at least once; otherwise output $\rho_+$.
    If $\rho=\rho_+$, the success probability is at least
    \begin{equation}
        (1-p_+)^5\ge\left(\frac{39}{40}\right)^5>\frac{2}{3}.
    \end{equation}
    If $\rho=\rho_-$, the success probability is at least
    \begin{equation}
        1-(1-p_-)^5\ge1-\left(\frac{31}{40}\right)^5>\frac{2}{3}.
\end{equation}
	Thus, we can discriminate the two cases with constant success probability.
	The query complexity is
	\begin{equation}
		\bigO{\frac{1}{\delta}} = \bigO{\frac{1}{\varepsilon}}.
	\end{equation}
\end{proof}

\begin{proof}[Proof of Theorem~\ref{Theorem:lower bound of samples}]
	Suppose that there exists a protocol which, given $N$ copies of $\rho$, implements channels $\mathcal{E}_\rho$ and $\mathcal{E}_\rho^\dagger$ that are $\varepsilon$-close in diamond norm to $\mathcal{U}_\rho$ and $\mathcal{U}_\rho^\dagger$, respectively.
	Here, $\rho$ is promised to be either $\rho_+$ or $\rho_-$.
	By Lemma~\ref{lemma:discriminate with queries}, one can discriminate the two cases using $\bigO{1/\varepsilon}$ queries to $\mathcal{E}_\rho$ and $\mathcal{E}_\rho^\dagger$.
	Therefore, the resulting discrimination procedure uses
	\begin{equation}
		\bigO{\frac{N}{\varepsilon}}
	\end{equation}
	copies of $\rho$.
	By Lemma~\ref{Lemma:lower bound of sample to discriminate the states}, however, every such discrimination procedure requires $\bigOmega{1/\delta^2}=\bigOmega{1/\varepsilon^2}$ copies since $\delta=\Theta(\varepsilon)$.
	Consequently,
	\begin{equation}
		N = \bigOmega{\frac{1}{\varepsilon}}.
	\end{equation}
\end{proof}

